import{z as C,x as i,o as r,c as A,q as o,j as t,D as e,d as l,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"昇腾 910 架构要点","description":"","frontmatter":{"title":"昇腾 910 架构要点","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ascend-910.md","filePath":"llm/ascend-910.md","lastUpdated":1791413859000}'),B={name:"llm/ascend-910.md"};function d(p,a,P,S,c,h){const E=i("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="昇腾-910-架构要点" tabindex="-1">昇腾 910 架构要点 <a class="header-anchor" href="#昇腾-910-架构要点" aria-label="Permalink to &quot;昇腾 910 架构要点&quot;">​</a></h1><div class="epigraph"><p>半精度 256 TFLOPS、整数 512 TOPS；达芬奇架构，设计功耗 350 W，达到规格算力时实测约 310 W。</p><footer>—— 华为 2019 年 8 月 23 日昇腾 910 与 MindSpore 发布会公开规格</footer></div><p><a href="/llm/jalapeno-ai-assisted-design">上一课</a>把 Jalapeño 的规格收在测量—验证—学习闭环里，自家模型参与 RTL 与内核搜索；那是另一条产品线的设计方法。缺口是课程要接到华为云端训练芯片：昇腾软件栈（CANN、MindSpore、后来的 MindIE）从哪一代核模型长出来。本课钉 2019 年 <strong>昇腾 910</strong> 的公开骨架：32 个达芬奇 AI Core、FP16 256 TFLOPS、INT8 512 TOPS。不重讲 OpenAI 的 PPA 对照，也不把 910C 的 128 GB 写回这一代。后课达芬奇三条流水默认已经读完本课的 SoC 轮廓。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>达芬奇核模型的第一代锚点要同时接住稠密矩阵乘、卷积/视觉预处理，以及当时的 TensorFlow / 自研 MindSpore。通用 GPU 用 SIMT 覆盖这一切；华为选择 Cube / Vector / Scalar 三条流水，见 <a href="/llm/davinci-cube-vector">下篇</a>。缺口是如何在单 Die 上铺 32 个这样的 AI Core，并配上足够的片上缓冲与片外高带宽内存，使训练任务喂得动。</p><p>发布会强调算力达到规格且功耗低于设计值，针对的是「高峰功耗不可部署」的质疑。对今天的 LLM 读者，910 的意义是昇腾软件栈（CANN、MindSpore、后来的 MindIE）的第一代云端锚点：图编译、算子库、集合通信都从这一代的核模型长出来。把 2024 年 910C 的双 Die 故事读回 910，会错核数、错内存、错互连。</p><h3 id="soc-而不只是加速器阵列" tabindex="-1">SoC 而不只是加速器阵列 <a class="header-anchor" href="#soc-而不只是加速器阵列" aria-label="Permalink to &quot;SoC 而不只是加速器阵列&quot;">​</a></h3><p>910 把 Task Scheduler、AI CPU、DVPP 放进同一颗芯片，是为了减少主机往返：视觉流水可以在 DVPP 上做缩放与色彩转换，标量/控制类算子可以落 AI CPU，矩阵落 AI Core。训练任务若每步都把预处理打回主机 CPU，PCIe 会先于 Cube 成为屋顶线。这一分工在后来的 LLM 推理里部分被 tokenizer 与主机侧调度取代，但核模型没有变：异构引擎，而不是单一 SIMT 池。</p><p><span class="marginnote">256 TFLOPS FP16 与 512 TOPS INT8 是峰值规格。真实训练利用率取决于算子是否走 Cube、是否能与搬运重叠、以及 HCCS/RoCE 上的梯度同步。不要把发布会峰值写成「任意网络的稳态吞吐」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 910 看成四块公开模块。<strong>AI Core 阵列</strong>：32 个达芬奇核，承担矩阵与向量密集计算。<strong>控制与调度</strong>：片上 CPU 与 Task Scheduler 把内核下发到 AI Core 或 AI CPU。<strong>DVPP</strong>：图像/视频预处理专用通路。<strong>存储与互连</strong>：AI Core 内侧是多级 Buffer（L0/L1/UB 等，细节见达芬奇篇），外侧是 HBM 类高带宽内存（2019 年 Hot Chips 相关介绍提到训练芯片用上 HBM2E 一类高带宽颗粒）；卡间走 HCCS，主机走 PCIe，多机可用 RoCE。软件上，2019 年同时发布 MindSpore；底层则是后来系统化的 <a href="/llm/cann-graph">CANN 图编译</a>。</p><p>系统产品把多颗 910 收进 Atlas 训练服务器与 Atlas 900 集群。华为全联接 2019 对 Atlas 900 给出过基于大量 910 互联的集群 FP16 算力量级（公开口径为数百到约一千 PFLOPS 量级的区间，随节点数变化）。集群数字用于理解「910 被设计成可堆叠」，不是本篇的单芯片规格。</p>',12)),(r(),t(s,null,{default:e(()=>[n(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20SOC%5B%22%E6%98%87%E8%85%BE%20910%20SoC%22%5D%0A%20%20%20%20CPU%5B%22%E6%8E%A7%E5%88%B6%20CPU%22%5D%0A%20%20%20%20TS%5B%22Task%20Scheduler%22%5D%0A%20%20%20%20AIC%5B%2232%20%C3%97%20%E8%BE%BE%E8%8A%AC%E5%A5%87%20AI%20Core%22%5D%0A%20%20%20%20ACPU%5B%22AI%20CPU%22%5D%0A%20%20%20%20DVPP%5B%22DVPP%22%5D%0A%20%20%20%20TS%20--%3E%20AIC%0A%20%20%20%20TS%20--%3E%20ACPU%0A%20%20%20%20CPU%20--%3E%20TS%0A%20%20end%0A%20%20AIC%20--%3E%20HBM%5B%22HBM%20%E7%B1%BB%E8%BF%91%E5%AD%98%22%5D%0A%20%20SOC%20--%3E%20HCCS%5B%22HCCS%20%2F%20PCIe%20%2F%20RoCE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="与-gpu-编程模型的差" tabindex="-1">与 GPU 编程模型的差 <a class="header-anchor" href="#与-gpu-编程模型的差" aria-label="Permalink to &quot;与 GPU 编程模型的差&quot;">​</a></h3><p>CUDA 程序员看到的是统一 SM 与全局内存。910 程序员看到的是：矩阵是否在 Cube 上、向量是否在 Vector 上、搬运是否走 MTE、同步是否用事件标志。CANN / TBE / Ascend C 把这些暴露成图或核函数。直接把 CUDA 核「翻译」过来，往往会得到标量路径，峰值 256 TFLOPS 与你无关。<span class="marginnote">初学者容易以为「代码能跑」就等于「用上了算力」：同一段矩阵乘，走 Scalar 慢路径可能只拿到峰值的一个零头。NPU 上「能算」与「算得快」之间隔着图编译与算子映射——这正是 CANN 存在的理由。</span>正确方法是让图编译把 MatMul 送到 Cube，把逐元素融合进 Vector，见 <a href="/llm/npu-friendly-ops">NPU 友好算子</a> 的一般原则。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>达芬奇核用 Cube 一个节拍完成固定尺寸的矩阵乘加（公开教材写 16×16 与 16×16 的矩阵乘形态），用累加器把部分和留在片上。<span class="marginnote">Cube 可以想象成一台只做一件事的压面机：一次吞进两小块 16×16 矩阵，吐出一块乘加结果。它对大块 GEMM 效率极高，但只认「方方正正的矩阵」；所以图编译要先把算子重排成它爱吃的形状，而不是让小算子排队绕路。</span>32 核并行给出芯片峰值。Vector 覆盖 FP16/FP32/INT8 等逐元素与归约，避免小算子打回主机。Scalar 负循环与地址，使另外两条流水可以异步前进。存储层次用片上 Buffer 减少对 HBM 的往返；HBM 提供训练激活与权重的容量与带宽。这一机制与后来 LLM decode 的带宽墙是同一屋顶线语言，只是 2019 年的主场景是训练的大 GEMM。</p>',4)),(r(),t(s,null,{default:e(()=>[n(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20OP%5B%22%E4%B8%80%E4%B8%AA%E8%AE%AD%E7%BB%83%E7%AE%97%E5%AD%90%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20M%5B%22%E7%9F%A9%E9%98%B5%E4%B9%98%E5%8A%A0%E9%83%A8%E5%88%86%22%5D%0A%20%20OP%20--%3E%20E%5B%22%E9%80%90%E5%85%83%E7%B4%A0%E4%B8%8E%E5%BD%92%E7%BA%A6%E9%83%A8%E5%88%86%22%5D%0A%20%20OP%20--%3E%20S%5B%22%E5%BE%AA%E7%8E%AF%E3%80%81%E5%9C%B0%E5%9D%80%E4%B8%8E%E8%B0%83%E5%BA%A6%22%5D%0A%20%20M%20--%3E%20CUBE%5B%22Cube%20%E6%B5%81%E6%B0%B4%EF%BC%9A%E6%95%B4%E5%9D%97%20GEMM%EF%BC%8C%E9%83%A8%E5%88%86%E5%92%8C%E7%95%99%E7%89%87%E4%B8%8A%22%5D%0A%20%20E%20--%3E%20VEC%5B%22Vector%20%E6%B5%81%E6%B0%B4%EF%BC%9AFP16%20%2F%20INT8%20%E9%80%90%E5%85%83%E7%B4%A0%22%5D%0A%20%20S%20--%3E%20SCA%5B%22Scalar%20%E6%B5%81%E6%B0%B4%EF%BC%9A%E8%AE%A9%E5%89%8D%E4%B8%A4%E6%9D%A1%E5%BC%82%E6%AD%A5%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20CUBE%20--%3E%20BUF%5B%22%E7%89%87%E4%B8%8A%20Buffer%EF%BC%8C%E5%87%8F%E5%B0%91%20HBM%20%E5%BE%80%E8%BF%94%22%5D%0A%20%20VEC%20--%3E%20BUF%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>功耗机制：350 W 设计包络给供电与散热；310 W 达到规格说明峰值点不在包络墙上。对机房，仍应按 350 W 与服务器整机功耗规划，不能按「实测 310」去堆密度。<span class="marginnote">为什么重要：按 310 W 规划机柜，一旦负载或环境让功耗回到 350 W 包络，供电与散热就没有余量，轻则降频、重则跳闸。数据中心按设计包络留冗余是铁律，实测峰值只是发布会的营销数字。</span></p><p><span class="marginnote">工艺节点的公开表述是 7nm 级 / 7nm+EUV，具体代工厂与后续 910B/C 因出口管制发生的流片变化，以华为当时官方口径为准，本文不推断未证实的代工厂细节。</span></p><h3 id="从训练卡到后来的推理栈" tabindex="-1">从训练卡到后来的推理栈 <a class="header-anchor" href="#从训练卡到后来的推理栈" aria-label="Permalink to &quot;从训练卡到后来的推理栈&quot;">​</a></h3><p>910 首先是训练规格。LLM 推理后来跑在 910B/910C 与 MindIE 上，见 <a href="/llm/mindie">MindIE</a>。架构连续性在于：仍然是达芬奇三维计算、仍然要图编译、仍然要集合通信。断裂在于：decode 小 batch、KV 缓存、连续批，这些不是 2019 年发布会的对象。读 910 是为了读懂核，不是为了抄 256 TFLOPS 去估 2026 年的 token/s。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把百科或媒体上未带华为文档的 910C 晶体管数、FP16 800 TFLOPS 等数字写进 910 这一篇。不要假设 32 核可以当 32 路独立 CUDA SM 做任意 SIMT。不要忽略 DVPP：视觉训练流水关掉它会把主机 CPU 打满。多机训练的梯度同步走 RoCE/HCCS 时，算法与 NCCL 同构，库与拓扑以 HCCL 文档为准。</p><p>910 的历史位置：它证明达芬奇可以上云端训练规模；软件栈从这一代开始必须处理图、算子缺口与多机。后续双 Die、UB 超节点是另一组产品，见 910C 与 CloudMatrix 公开论文，不要在本篇展开未属于 910 的规格。</p><p><span class="marginnote">出处：华为 2019-08-23 昇腾 910 / MindSpore 发布规格；Hot Chips 相关达芬奇/910 公开介绍中的 32 核与工艺表述；《Huawei Atlas AI Computing Solution》等公开教材中的 SoC 模块划分。不编造未公布的 HBM 容量与单核频率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>昇腾 910：32 达芬奇核，FP16 256 TFLOPS，INT8 512 TOPS，设计 350 W / 达标约 310 W。</li><li>SoC 含控制 CPU、AI CPU、DVPP、Task Scheduler，不只是矩阵阵列。</li><li>存储为 HBM 类近存，互连含 HCCS、PCIe、RoCE 等公开接口族。</li><li>编程走 CANN 图与 Cube/Vector 映射，不是 CUDA SIMT。</li><li>本篇规格停在 2019 代；910C 双 Die 另文。</li><li>出处：华为 2019 发布会与公开架构教材。</li></ul>',10))])}const m=C(B,[["render",d]]);export{T as __pageData,m as default};
